const rows = $input.all().map(i => i.json);
const total = rows.length;
const cols = total ? Object.keys(rows[0]) : [];
const ne = (v) => v !== undefined && v !== null && String(v).trim() !== '';
const count = (fn) => rows.filter(fn).length;
const tally = (field) => {
  const out = {};
  for (const r of rows) {
    const k = ne(r[field]) ? String(r[field]).slice(0, 40) : '(blank)';
    out[k] = (out[k] || 0) + 1;
  }
  return out;
};

return [{ json: {
  columns: cols,
  total_rows: total,
  by_source: tally('source'),
  by_enriched_status: tally('enriched_status'),
  by_status: tally('status'),
  by_email_source: tally('email_source'),
  has_email: count(r => ne(r.email)),
  has_company_name: count(r => ne(r.company_name)),
  has_company_domain: count(r => ne(r.company_domain)),
  email_verified_true: count(r => String(r.email_verified).toLowerCase() === 'true'),
  email_confidence_gte_70: count(r => Number(r.email_confidence) >= 70),
  already_emailed: count(r => ne(r.email_sent_at)),
  replied: count(r => ne(r.replied_at)),
  linkedin_outreach_sent: count(r => ne(r.outreach_sent_at)),
  sendable_loose: count(r => ne(r.email) && !ne(r.email_sent_at) && !ne(r.replied_at)),
  samples_with_email: rows.filter(r => ne(r.email)).slice(0, 3).map(r => ({ name: r.name, company_name: r.company_name, company_domain: r.company_domain, email: r.email, email_source: r.email_source, email_confidence: r.email_confidence, email_verified: r.email_verified, source: r.source })),
  samples_no_email: rows.filter(r => !ne(r.email)).slice(0, 3).map(r => ({ name: r.name, headline: String(r.headline || '').slice(0, 60), company_name: r.company_name, company_domain: r.company_domain, enriched_status: r.enriched_status, source: r.source }))
}}];
